        self.quality_label = QLabel("-")
        self.quality_label.setFont(QFont("Arial", 10, QFont.Bold))
        info_layout.addWidget(QLabel("Quality Score:"), 1, 0)
        info_layout.addWidget(self.quality_label, 1, 1)
        
        self.sharpness_label = QLabel("-")
